<?php
declare(strict_types=1);
namespace App\Application\Academic\Commands;
use Illuminate\Database\Connection;
use App\Infrastructure\Authentication\AuthenticatedActor;
use App\Application\Academic\AcademicCommandFailure;
use App\Infrastructure\Persistence\Academic\{AcademicLockSet,AcademicWriteTransaction,AcademicMutationResult,LifecycleEvent,LocalMaterialStorage};
final class MaterialObservations {
 public function __construct(private Connection $db,private LocalMaterialStorage $storage){}
 private function roles(AuthenticatedActor $a):array {FoundationCommandChecks::credentials($this->db,$a);if($this->db->table('retained_identities')->where('id',$a->identityId)->value('credential_status')!=='active')throw new AcademicCommandFailure('forbidden');return $this->db->table('local_role_grants')->where('identity_id',$a->identityId)->pluck('role')->all();}
 private function vice(AuthenticatedActor $a):void {if(!in_array('vice_principal',$this->roles($a),true))throw new AcademicCommandFailure('not_found');}
 public function material(AuthenticatedActor $a,string $id):array {$roles=$this->roles($a);if(!array_intersect($roles,['vice_principal','teacher']))throw new AcademicCommandFailure('not_found');$m=$this->db->table('course_materials')->where('id',AcademicLockSet::id($id))->first();if(!$m||(!in_array('vice_principal',$roles,true)&&(!in_array('teacher',$roles,true)||(string)$m->author_id!==$a->identityId)))throw new AcademicCommandFailure('not_found');return (array)$m;}
 private function active(array $m):bool {$a=$this->db->table('teaching_assignments')->where('id',$m['assignment_id'])->first();return $a&&$a->state==='active'&&$this->db->table('academic_periods')->where('id',$a->academic_period_id)->value('state')==='active';}
 private function revision(string $material):?string {$id=(new MaterialMaintenance($this->db))->current($material)['id']??null;return $id===null?null:(string)$id;}
 private function metadata(array $m,?string $revision):array {if($revision===null)return ['title'=>$m['title'],'description'=>$m['description']];$r=$this->db->table('material_revisions')->where('material_id',$m['id'])->where('id',$revision)->first();if(!$r)throw new AcademicCommandFailure('reference_unavailable');return ['title'=>$r->title,'description'=>$r->description];}
 public function courses(AuthenticatedActor $a,?string $after):array {$this->vice($a);return (new \App\Application\Academic\Queries\AssignmentDirectoryQuery($this->db))->page($a,'assignments',$after);}
 public function materials(AuthenticatedActor $a,string $assignment,?string $after):array {$this->vice($a);$assignment=AcademicLockSet::id($assignment);if(!$this->db->table('teaching_assignments')->where('id',$assignment)->exists())throw new AcademicCommandFailure('not_found');$q=$this->db->table('course_materials')->where('assignment_id',$assignment);if($after!==null)$q->where('id','>',AcademicLockSet::id($after));$rows=$q->orderBy('id')->limit(51)->get();$items=[];$service=new CourseMaterials($this->db,$this->storage);foreach($rows->take(50) as $row){$m=(array)$row;$r=(new MaterialMaintenance($this->db))->current((string)$m['id']);$visible=$r?array_replace(MaterialFiles::at($this->db,$m,(string)$r['id']),['title'=>$r['title'],'description'=>$r['description']]):$m;$items[]=$service->view($visible)+['revision_id'=>$r?(string)$r['id']:null,'state'=>$r['state']??'active','can_observe'=>$this->active($m)];}return ['items'=>$items,'next_after'=>$rows->count()>50?end($items)['id']:null];}
 public function file(AuthenticatedActor $a,string $id):array {$this->vice($a);$m=$this->material($a,$id);$m=MaterialFiles::at($this->db,$m,$this->revision($id));return [$this->storage->verify($m),$m];}
 private function original(AuthenticatedActor $a,string $id):array {$roles=$this->roles($a);if(!array_intersect($roles,['vice_principal','teacher']))throw new AcademicCommandFailure('not_found');$q=$this->db->table('material_observations')->where('id',AcademicLockSet::id($id));if(!in_array('vice_principal',$roles,true))$q->where('recipient_id',$a->identityId);$r=$q->first();if(!$r)throw new AcademicCommandFailure('not_found');return (array)$r;}
 private function current(string $id):?array {$r=$this->db->table('material_observation_states as s')->join('material_observation_events as e','e.id','=','s.current_event_id')->where('s.observation_id',$id)->first('e.*');return $r?(array)$r:null;}
 public function detail(AuthenticatedActor $a,string $id):array {
  $o=$this->original($a,$id);$m=$this->material($a,(string)$o['material_id']);$roles=$this->roles($a);$current=$this->current((string)$o['id']);$state=$current?($current['operation']==='replied'?'respondida':'revisada'):'observada';$snapshot=$this->metadata($m,$o['observed_revision_id']===null?null:(string)$o['observed_revision_id']);$reply=$current?($current['operation']==='replied'?(object)$current:$this->db->table('material_observation_events')->where('id',$current['previous_event_id'])->first()):null;$replyData=null;if($reply){$ref=$reply->material_revision_id===null?null:(string)$reply->material_revision_id;$meta=$this->metadata($m,$ref);$replyData=['id'=>(string)$reply->id,'body'=>$reply->body,'revision_id'=>$ref,'title'=>$meta['title'],'description'=>$meta['description'],'created_at'=>$reply->created_at];}
  $labels=new \App\Infrastructure\Persistence\Academic\LocalIdentityLabels($this->db);$creator=$labels->displayName((string)$o['creator_id']);$recipient=$labels->displayName((string)$o['recipient_id']);if($creator===null||$recipient===null)throw new AcademicCommandFailure('reference_unavailable');
  $currentRevision=$this->revision((string)$m['id']);$currentMeta=$this->metadata($m,$currentRevision);
  return ['id'=>(string)$o['id'],'material_id'=>(string)$m['id'],'creator_name'=>$creator,'recipient_name'=>$recipient,'body'=>$o['body'],'created_at'=>$o['created_at'],'observed_revision_id'=>$o['observed_revision_id']===null?null:(string)$o['observed_revision_id'],'observed_title'=>$snapshot['title'],'observed_description'=>$snapshot['description'],'state'=>$state,'event_id'=>$current?(string)$current['id']:null,'reply'=>$replyData,'reviewed_at'=>$state==='revisada'?$current['created_at']:null,'current_revision_id'=>$currentRevision,'current_title'=>$currentMeta['title'],'current_description'=>$currentMeta['description'],'can_reply'=>$state==='observada'&&in_array('teacher',$roles,true)&&(string)$o['recipient_id']===$a->identityId&&$this->active($m),'can_review'=>$state==='respondida'&&in_array('vice_principal',$roles,true)&&$this->active($m)];
 }
 public function page(AuthenticatedActor $a,string $material,?string $after):array {$this->material($a,$material);$q=$this->db->table('material_observations')->where('material_id',$material);if($after!==null)$q->where('id','>',AcademicLockSet::id($after));$rows=$q->orderBy('id')->limit(51)->pluck('id');$items=[];foreach($rows->take(50) as $id)$items[]=$this->detail($a,(string)$id);return ['items'=>$items,'next_after'=>$rows->count()>50?end($items)['id']:null];}
 private function expected(mixed $id):?string {if($id===null)return null;if(!is_string($id))throw new AcademicCommandFailure('invalid_input');return AcademicLockSet::id($id);}
 private function body(mixed $body):string {if(!is_string($body)||trim($body)===''||mb_strlen($body)>5000)throw new AcademicCommandFailure('invalid_input');return $body;}
 public function execute(AuthenticatedActor $a,string $target,string $operation,array $input):array {
  if(!in_array($operation,['observe','reply','review'],true))throw new AcademicCommandFailure('invalid_input');$target=AcademicLockSet::id($target);$roles=$this->roles($a);if(in_array($operation,['observe','review'],true))$this->vice($a);
  $fields=match($operation){'observe'=>['expected_revision_id','body'],'reply'=>['expected_event_id','expected_revision_id','body'],'review'=>['expected_event_id']};FoundationCommandChecks::fields($input,$fields,$fields);$revision=$operation==='review'?null:$this->expected($input['expected_revision_id']);$expected=$operation==='observe'?null:$this->expected($input['expected_event_id']);$body=$operation==='review'?null:$this->body($input['body']);$o=$operation==='observe'?null:$this->original($a,$target);$m=$this->material($a,$operation==='observe'?$target:(string)$o['material_id']);$current=null;
  return (new AcademicWriteTransaction($this->db))->execute($a->identityId,
   function()use($m){$assignment=$this->db->table('teaching_assignments')->where('id',$m['assignment_id'])->first();return new AcademicLockSet(['academic_periods'=>[(string)$assignment->academic_period_id],'retained_identities'=>[(string)$m['author_id']],'teaching_assignments'=>[(string)$assignment->id]]);},
   function()use($a,$operation,$m,$revision,$expected,$o,&$current){$roles=$this->roles($a);$this->material($a,(string)$m['id']);if(in_array($operation,['observe','review'],true))$this->vice($a);elseif(!in_array('teacher',$roles,true)||(string)$o['recipient_id']!==$a->identityId)throw new AcademicCommandFailure('not_found');if(!$this->active($m))throw new AcademicCommandFailure('invalid_transition');if($operation!=='review'&&$this->revision((string)$m['id'])!==$revision)throw new AcademicCommandFailure('stale_material_revision');if($operation!=='observe'){$this->original($a,(string)$o['id']);$this->db->table('material_observation_states')->where('observation_id',$o['id'])->lockForUpdate()->first();$current=$this->current((string)$o['id']);if(($current?(string)$current['id']:null)!==$expected)throw new AcademicCommandFailure('stale_observation');if(($operation==='reply'&&$current!==null)||($operation==='review'&&(!$current||$current['operation']!=='replied')))throw new AcademicCommandFailure('invalid_transition');}return true;},
   function($context,$boundary)use($a,$operation,$m,$o,$body,$revision,&$current){$stamp=$boundary->timestamp->format('Y-m-d H:i:s.u');if($operation==='observe'){$id=(string)$this->db->table('material_observations')->insertGetId(['material_id'=>$m['id'],'creator_id'=>$a->identityId,'recipient_id'=>$m['author_id'],'observed_revision_id'=>$revision,'body'=>$body,'operation_key'=>$boundary->toServerKey(),'created_at'=>$stamp]);$event=null;}else{$id=(string)$o['id'];$event=(string)$this->db->table('material_observation_events')->insertGetId(['observation_id'=>$id,'actor_id'=>$a->identityId,'material_revision_id'=>$this->revision((string)$m['id']),'previous_event_id'=>$current?(string)$current['id']:null,'operation'=>$operation==='reply'?'replied':'reviewed','body'=>$body,'operation_key'=>$boundary->toServerKey(),'created_at'=>$stamp]);if($current)$this->db->table('material_observation_states')->where('observation_id',$id)->update(['current_event_id'=>$event]);else $this->db->table('material_observation_states')->insert(['observation_id'=>$id,'current_event_id'=>$event]);}return new AcademicMutationResult(['id'=>$id,'event_id'=>$event],[new LifecycleEvent('assignment',(string)$m['assignment_id'],'material_observation_'.$operation,'active','active',['material_id'=>(string)$m['id'],'observation_id'=>$id])]);});
 }
}
